ecommerce.storeConfigExample:
import { StoreHomePage, demoStore, type StoreConfig } from 'react-component-kit-ui/templates/ecommerce';

const store: StoreConfig = {
  ...demoStore,
  name: 'My Shop',
  currency: 'EUR',
  locale: 'es-ES',
  cartKey: 'my-shop-cart',
  products: [
    {
      slug: 'linen-shirt',
      name: 'Linen Shirt',
      price: 59,
      category: 'apparel',
      image: '/products/linen-shirt.webp', // or icon: 'shirt'
      sizes: ['S', 'M', 'L'],
      rating: 4.7,
      reviews: 40,
    },
  ],
};

export default function Page() {
  return <StoreHomePage store={store} routes={{ home: '/', shop: '/shop/', product: '/product/', checkout: '/checkout/' }} />;
}

